import type { SoundKeyframe } from "./types";

export interface EmoteSoundsOptions {
  resolve: (soundId: string) => string | null | undefined;
  enabled?: boolean;
  volume?: number;
}

const MIN_RATE = 0.25;
const MAX_RATE = 4;

export class EmoteSounds {
  private readonly resolve: (soundId: string) => string | null | undefined;
  private readonly volume: number;
  private readonly playing = new Set<HTMLAudioElement>();
  private enabled: boolean;

  constructor(options: EmoteSoundsOptions) {
    this.resolve = options.resolve;
    this.enabled = options.enabled ?? false;
    this.volume = clamp(options.volume ?? 1, 0, 1);
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (!enabled) this.stopAll();
  }

  play(keyframe: SoundKeyframe): void {
    if (!this.enabled || typeof Audio === "undefined") return;
    const url = this.resolve(keyframe.soundId);
    if (!url) return;

    const audio = new Audio(url);
    audio.volume = clamp(keyframe.volume, 0, 1) * this.volume;
    audio.playbackRate = clamp(keyframe.pitch || 1, MIN_RATE, MAX_RATE);
    audio.addEventListener("ended", () => this.playing.delete(audio));
    this.playing.add(audio);

    void audio.play().catch(() => this.playing.delete(audio));
  }

  stopAll(): void {
    for (const audio of this.playing) {
      audio.pause();
      audio.src = "";
    }
    this.playing.clear();
  }

  dispose(): void {
    this.stopAll();
  }
}

function clamp(value: number, min: number, max: number): number {
  if (!Number.isFinite(value)) return min;
  return Math.min(Math.max(value, min), max);
}
